using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EyedTalismanOmenData", menuName = "Data/Battle/Omens System/Omen Data/Event/EyedTalismanOmenData")]
public class EyedTalismanOmenData : OnStartOfTurnOmenData
{
	[SerializeField]
	private OmenLogicActionFace omenLogicActionFace;

	public override void ActivateOmen(GameObject target = null)
	{
		bool num = counter + 1 == TriggerAmount;
		if (counter <= TriggerAmount)
		{
			ActivateOmen(ActionValue, target);
			omenInstance.UpdateOmenCounter();
		}
		if (num)
		{
			omenInstance.SetIgnoreStartOfTurnUpdateOmenCounterForTheRestOfBattle(ignoreStartOfTurnUpdateOmenCounterForTheRestOfBattle: true);
			omenInstance.DisableOmen();
			omenInstance.ToggleOmenCounter(toggle: false);
		}
		omenLogicActionFace.ActivateOmen();
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), TriggerAmount, GetOmenConvertedDescriptionBattleAction().LowercaseFirst()) + "\n" + base.localizationManager.GetLocalizedAtTheStartOfYourTurn() + base.localizationManager.GetLocalizedSpace() + omenLogicActionFace.GetActionDescription();
	}
}
